<script setup lang="ts">import{Head,Link,useForm}from'@inertiajs/vue3';import AuthenticatedLayout from'../../Layouts/AuthenticatedLayout.vue';import InventorySkuCombobox from'./components/InventorySkuCombobox.vue';type Item={id:number;product:{id:number;sku:string;name:string};quantity_on_hand:number;quantity_reserved:number;quantity_available:number;inbound_at:string|null;stay_days:number|null;location:string|null;standard_qoh:number|null;expected_restock_qty:number};type W={id:number;slug:string;code:string;name:string;country_code:string|null;address_line1:string|null;address_line2:string|null;city:string|null;state_region:string|null;postal_code:string|null;timezone:string|null;type:string;ownership_type:'owned'|'external';is_active:boolean;priority:number;billing_markdown:string|null;service_regions:string[];inventories:Item[]};const props=defineProps<{warehouse:W;canOperate:boolean;canManage:boolean}>();const breadcrumbs=[{label:'BYL ERP',href:'/dashboard'},{label:'库存',href:'/inventory'},{label:'仓库清单',href:'/inventory/list'},props.warehouse.name];const meta=useForm({name:props.warehouse.name,code:props.warehouse.code,country_code:props.warehouse.country_code||'',address_line1:props.warehouse.address_line1||'',address_line2:props.warehouse.address_line2||'',city:props.warehouse.city||'',state_region:props.warehouse.state_region||'',postal_code:props.warehouse.postal_code||'',timezone:props.warehouse.timezone||'',type:props.warehouse.type,ownership_type:props.warehouse.ownership_type,is_active:props.warehouse.is_active,priority:props.warehouse.priority});const billing=useForm({billing_markdown:props.warehouse.billing_markdown||''});const regions=useForm({country_codes:props.warehouse.service_regions.join(', ')} as any);const stock=useForm({product_id:null as number|null,sku:'',quantity_on_hand:0,quantity_reserved:0,inbound_at:'',location:'',standard_qoh:null as number|null,expected_restock_qty:0});const saveMeta=()=>meta.patch(`/inventory/${props.warehouse.slug}`);const saveBilling=()=>billing.patch(`/inventory/${props.warehouse.slug}/billing`);const saveRegions=()=>{const codes=String(regions.country_codes||'').split(',').map(x=>x.trim().toUpperCase()).filter(Boolean);regions.transform(()=>({country_codes:codes})).patch(`/inventory/${props.warehouse.slug}/regions`,{onFinish:()=>regions.defaults()})};const addStock=()=>stock.transform(d=>({product_id:d.product_id,quantity_on_hand:d.quantity_on_hand,quantity_reserved:d.quantity_reserved,inbound_at:d.inbound_at||null,location:d.location||null,standard_qoh:d.standard_qoh,expected_restock_qty:d.expected_restock_qty})).post(`/inventory/${props.warehouse.slug}/stock`,{onSuccess:()=>stock.reset()});const quick=(item:Item)=>{const f=useForm({quantity_on_hand:item.quantity_on_hand,quantity_reserved:item.quantity_reserved,inbound_at:item.inbound_at||'',location:item.location||'',standard_qoh:item.standard_qoh,expected_restock_qty:item.expected_restock_qty});f.patch(`/inventory/${props.warehouse.slug}/stock/${item.id}`)}</script>
<template><Head :title="`${warehouse.name} · BYL ERP`"/><AuthenticatedLayout :title="warehouse.name" :breadcrumbs="breadcrumbs"><section class="mvp-page"><div class="mvp-page-heading"><div><p class="mvp-kicker">Warehouse Detail</p><h2>{{warehouse.name}}</h2><p>{{warehouse.code}} · {{warehouse.country_code||'国家未填写'}}</p></div><Link class="mvp-button" href="/inventory/products">全部产品库存</Link></div>
<div class="mvp-card"><h3>仓库信息</h3><form v-if="canManage" class="grid" @submit.prevent="saveMeta"><label>名称<input v-model="meta.name"></label><label>代码<input v-model="meta.code"></label><label>国家<input v-model="meta.country_code" maxlength="2"></label><label>地址1<input v-model="meta.address_line1"></label><label>地址2<input v-model="meta.address_line2"></label><label>城市<input v-model="meta.city"></label><label>州/省<input v-model="meta.state_region"></label><label>邮编<input v-model="meta.postal_code"></label><label>时区<input v-model="meta.timezone"></label><label>仓库归属<select v-model="meta.ownership_type"><option value="owned">自有仓</option><option value="external">外部仓</option></select></label><label>优先级<input v-model.number="meta.priority" type="number"></label><label>状态<select v-model="meta.is_active"><option :value="true">启用</option><option :value="false">停用</option></select></label><button class="mvp-button mvp-button-primary">💾 保存仓库信息</button></form><div v-else><p>{{[warehouse.address_line1,warehouse.address_line2,warehouse.city,warehouse.state_region,warehouse.postal_code,warehouse.country_code].filter(Boolean).join(', ')||'地址未填写'}}</p></div></div>
<div class="mvp-card"><h3>服务国家/地区</h3><form v-if="canManage" class="row" @submit.prevent="saveRegions"><input v-model="regions.country_codes" placeholder="US, CA, DE"><button class="mvp-button">💾 保存</button></form><p v-else>{{warehouse.service_regions.join(', ')||'未配置'}}</p><small>仅记录真实服务范围；未配置时 Shipping 不应猜测。</small></div>
<div v-if="canOperate" class="mvp-card"><h3>增加 / 更新产品库存</h3><form class="stock-grid" @submit.prevent="addStock"><label>SKU / 产品<InventorySkuCombobox v-model="stock.sku" v-model:product-id="stock.product_id"/></label><label>当前库存<input v-model.number="stock.quantity_on_hand" type="number" min="0"></label><label>预留<input v-model.number="stock.quantity_reserved" type="number" min="0"></label><label>上架时间<input v-model="stock.inbound_at" type="date"></label><label>Location<input v-model="stock.location"></label><label>Standard QoH<input v-model.number="stock.standard_qoh" type="number" min="0"></label><label>预计备货<input v-model.number="stock.expected_restock_qty" type="number" min="0"></label><button class="mvp-button mvp-button-primary" :disabled="!stock.product_id">💾 保存库存</button></form></div>
<div class="mvp-card table-wrap"><h3>仓库产品</h3><table><thead><tr><th>SKU</th><th>产品</th><th>上架时间</th><th>停留</th><th>Location</th><th>当前</th><th>预留</th><th>可用</th><th>Standard QoH</th><th>预计备货</th><th v-if="canOperate">操作</th></tr></thead><tbody><tr v-for="i in warehouse.inventories" :key="i.id"><td><strong>{{i.product.sku}}</strong></td><td>{{i.product.name}}</td><td>{{i.inbound_at||'—'}}</td><td>{{i.stay_days===null?'—':`${i.stay_days} 天`}}</td><td>{{i.location||'—'}}</td><td>{{i.quantity_on_hand}}</td><td>{{i.quantity_reserved}}</td><td><strong>{{i.quantity_available}}</strong></td><td>{{i.standard_qoh??'—'}}</td><td>{{i.expected_restock_qty}}</td><td v-if="canOperate"><button class="mvp-button" @click="quick(i)">💾 Save</button></td></tr><tr v-if="!warehouse.inventories.length"><td :colspan="canOperate?11:10">暂无产品库存</td></tr></tbody></table></div>
<details class="mvp-card"><summary><strong>仓库计费表（Markdown）</strong></summary><pre class="markdown">{{billing.billing_markdown||'未填写仓库计费表'}}</pre><form v-if="canManage" @submit.prevent="saveBilling"><textarea v-model="billing.billing_markdown" rows="14" placeholder="粘贴或编辑 Markdown 文档"></textarea><button class="mvp-button mvp-button-primary">💾 保存计费表</button></form></details>
</section></AuthenticatedLayout></template>
<style scoped>.grid,.stock-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.grid label,.stock-grid label{display:flex;flex-direction:column;gap:5px;font-size:13px}.grid input,.grid select,.stock-grid input,.row input,textarea{padding:9px;border:1px solid #dbe2e8;border-radius:8px;width:100%}.row{display:flex;gap:8px}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse}th,td{padding:9px;border-bottom:1px solid #e5e7eb;text-align:left;white-space:nowrap}.markdown{white-space:pre-wrap;background:#f8fafc;padding:14px;border-radius:8px;overflow:auto}details summary{cursor:pointer;margin-bottom:12px}@media(max-width:850px){.grid,.stock-grid{grid-template-columns:1fr}}</style>
